export function buildingAppearance(b) {
  let fallback={facade:'punched',color:'#b7b4a6',trim:'#c8c5b8',glass:'#485f65',spacing:3.3};
  if(/college|house|apartments|village|terrace/i.test(b.name))fallback={...fallback,facade:'brick',color:'#a38b70',trim:'#c8c6bb',spacing:2.8};
  if(/carpark/i.test(b.name))fallback={...fallback,facade:'parking',color:'#a5a59a',trim:'#c7c7ba'};
  if(/old tote|white house|regiment|fig tree theatre/i.test(b.name))fallback={...fallback,facade:'brick',color:'#aa795b'};
  return {...fallback,...profiles[b.id]};
}
